def validate_acceptance(receipt,confirmation):
    exact(confirmation,CONFIRMATION,'confirmation changed')
    exact({k:v for k,v in receipt.items() if k!='text'},RECEIPT,'receipt fields changed')
    raw=receipt['text'].encode('utf-8')
    if sha(raw)!=RECEIPT['sha256'] or len(raw)!=RECEIPT['size_bytes']:raise ValueError('complete user message changed')
    return True

def source_lines(sources):
    if type(sources) is not dict or set(sources)!={row['path'] for row in SOURCE_BINDINGS}:raise ValueError('exact sources required')
    result={}
    for binding in SOURCE_BINDINGS:
        raw=sources[binding['path']]
        if type(raw) is not bytes or len(raw)!=binding['size_bytes'] or sha(raw)!=binding['sha256']:raise ValueError('source byte binding changed')
        raw.decode('utf-8','strict')
        if b'\0' in raw:raise ValueError('NUL source')
        lines=raw.split(b'\n');lines=[line+b'\n' for line in lines[:-1]]+([lines[-1]] if lines[-1] else [])
        offsets=[];offset=0
        for line in lines:offsets.append(offset);offset+=len(line)
        result[binding['path']]=(raw,lines,offsets,binding)
    return result

def anchor(views,index,line):
    path=SOURCE_BINDINGS[index]['path'];raw,lines,offsets,binding=views[path]
    integer(line,1,len(lines),'line outside source');content=lines[line-1]
    return {'path':path,'source_sha256':binding['sha256'],'line_number':line,'line_start_byte':offsets[line-1],'line_length_bytes':len(content),'raw_line_sha256':sha(content),'full_line_text':content.decode('utf-8'),'source_role':binding['role']}

def span_anchor(views,index,start,end):
    path=SOURCE_BINDINGS[index]['path'];raw,lines,offsets,binding=views[path]
    integer(start,1,len(lines),'span start');integer(end,start,len(lines),'span end')
    first=offsets[start-1];last=offsets[end-1]+len(lines[end-1]);content=raw[first:last]
    return {'path':path,'source_sha256':binding['sha256'],'start_line':start,'end_line':end,'start_byte':first,'length_bytes':len(content),'span_sha256':sha(content),'source_role':binding['role']}

def review_report(sources,inventory):
    views=source_lines(sources)
    if canonical(inventory)!=INVENTORY_SHA:raise ValueError('complete accepted361 inventory changed')
    definitions=[]
    for i,hint in enumerate(inventory['hint_records']):
        if hint['kind']=='function-definition-hint':
            match=re.match(r'\s*(?:function\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(\)\s*\{',hint['snippet'])
            definitions.append({'inventory_index':i,'name_candidate':match.group(1) if match else None,'anchor':hint,'status':'definition-like-text-not-resolved-runtime-function'})
    sites=[]
    for index,line,key,target,context,literal in SITES:
        loc=anchor(views,index,line)
        if loc['full_line_text'].rstrip('\n')!=literal:raise ValueError('reviewed literal changed')
        candidates=[item['inventory_index'] for item in definitions if item['name_candidate']==target and item['anchor']['path']==loc['path']]
        sites.append({'id':key,'target_text':target,'context_review':context,'anchor':loc,'candidate_same_source_definition_indices':candidates,'relation_status':'source-text-context-reviewed-runtime-edge-unresolved','actual_callee_binding':None,'reachability_proven':False,'native_effects_proven':False})
    spans=[{'id':key,'anchor':span_anchor(views,index,start,end),'status':'whole-selected-span-reviewed-without-shell-evaluation'} for index,start,end,key in SPANS]
    by_kind={kind:[i for i,hint in enumerate(inventory['hint_records']) if hint['kind']==kind] for kind in KINDS}
    body=sources[SOURCE_BINDINGS[1]['path']];generated=sources[SOURCE_BINDINGS[3]['path']]
    offset=generated.find(body)
    if offset!=4039 or generated.count(body)!=1:raise ValueError('exact historical body copy missing or duplicated')
    copy={'body_source':SOURCE_BINDINGS[1]['path'],'generated_source':SOURCE_BINDINGS[3]['path'],'start_byte':offset,'start_line':48,'length_bytes':len(body),'sha256':sha(body),'occurrences':1,'byte_identity_verified':True,'independent_worker':False,'embedded_reference_decoded':False,'embedded_config_decoded':False,'runtime_consumption_identity_proven':False,'historical_constants_current_authority':False}
    return {'schema':1,'step':362,'scope':'repository-source-inventory-and-roadmap-workstream359-368-only','review_sources':SOURCE_BINDINGS,'inventory_canonical_sha256':INVENTORY_SHA,'selected_spans':spans,'selected_sites':sites,'definition_like_register':definitions,'complete_lexical_partition':by_kind,'copy_relationship':copy,'unresolved_relations':UNRESOLVED,'coverage':{'inventory_records':len(inventory['hint_records']),'definition_like_records':len(definitions),'selected_span_count':len(spans),'selected_site_count':len(sites),'shell_parsed':False,'complete_call_graph_claimed':False,'all_inventory_records_retained_as_unresolved':True,'selected_sites_are_not_exhaustive':True,'installed_versions_bound':False,'no_hint_means_no_effects':False},'boundaries':BOUNDARIES}

def validate_review(report,sources,inventory):
    return exact(report,review_report(sources,inventory),'review data changed or native promotion attempted')
